import test from 'node:test';
import assert from 'node:assert/strict';

import {
  clip,
  doneMessage,
  formatName,
  initials,
  isActive,
  lastN,
  splitLines,
} from '../src/lib/text.ts';

test('exports the corrected success message', () => {
  assert.equal(doneMessage, 'Submitted successfully');
});

test('formats names by trimming surrounding whitespace', () => {
  assert.equal(formatName('  Ada Lovelace  '), 'Ada Lovelace');
});

test('returns the supplied active state', () => {
  assert.equal(isActive(true), true);
  assert.equal(isActive(false), false);
});

test('returns no initials for empty input', () => {
  assert.equal(initials(''), '');
});

test('returns exactly the requested number of trailing items', () => {
  assert.deepEqual(lastN([1, 2, 3, 4], 2), [3, 4]);
});

test('splits Unix and Windows line endings', () => {
  assert.deepEqual(splitLines('one\ntwo\r\nthree'), ['one', 'two', 'three']);
});

test('clips text to 280 characters', () => {
  const longText = 'a'.repeat(281);
  assert.equal(clip(longText), 'a'.repeat(280));
  assert.equal(clip('short'), 'short');
});
